/**
 * White Caves Real Estate - Standalone Native PDF-1.7 Stamping, Multi-Page Addendum, Payment Receipt & Binary Compiler
 * Supports stamping text & vector tick marks onto existing DLD template pages (Pages 1-3)
 * AND appending newly generated A4 Addendum pages (Pages 4-6) and Payment Receipt page (Page 7)
 * into a single valid PDF-1.7 binary.
 */

(function (globalScope) {
    function bytesToLatin1(uint8) {
        let out = "";
        const chunk = 0x8000;
        for (let i = 0; i < uint8.length; i += chunk) {
            out += String.fromCharCode.apply(null, uint8.subarray(i, i + chunk));
        }
        return out;
    }

    function latin1ToBytes(str) {
        const out = new Uint8Array(str.length);
        for (let i = 0; i < str.length; i++) {
            out[i] = str.charCodeAt(i) & 0xff;
        }
        return out;
    }

    function escapePdfLiteralString(text) {
        return String(text)
            .replace(/[\u2018\u2019]/g, "'")
            .replace(/[\u201C\u201D]/g, '"')
            .replace(/[\u2013\u2014]/g, "-")
            .replace(/\\/g, "\\\\")
            .replace(/\(/g, "\\(")
            .replace(/\)/g, "\\)")
            .replace(/\r/g, "")
            .replace(/\n/g, " ");
    }

    class NativePageProxy {
        constructor(pageIndex, pageObjId, isNewPage = false) {
            this.pageIndex = pageIndex;
            this.pageObjId = pageObjId;
            this.isNewPage = isNewPage;
            this.operations = [];
            this.lines = [];
            this.rects = [];
            this.polygons = [];
        }

        drawText(text, options = {}) {
            if (text === undefined || text === null || String(text).trim() === "") return;
            this.operations.push({
                text: String(text),
                x: Number(options.x || 0),
                y: Number(options.y || 0),
                size: Number(options.size || 8.5),
                bold: options.bold !== undefined ? Boolean(options.bold) : !this.isNewPage,
                color: options.color || (this.isNewPage ? { r: 0.08, g: 0.09, b: 0.12 } : { r: 0.05, g: 0.12, b: 0.28 })
            });
        }

        drawLine(options = {}) {
            const start = options.start || { x: 45, y: 400 };
            const end = options.end || { x: 550, y: 400 };
            this.lines.push({
                x1: Number(start.x),
                y1: Number(start.y),
                x2: Number(end.x),
                y2: Number(end.y),
                thickness: Number(options.thickness || 0.75),
                color: options.color || { r: 0.2, g: 0.2, b: 0.2 }
            });
        }

        drawRectangle(options = {}) {
            this.rects.push({
                x: Number(options.x || 0),
                y: Number(options.y || 0),
                width: Number(options.width || 100),
                height: Number(options.height || 40),
                borderWidth: Number(options.borderWidth !== undefined ? options.borderWidth : 0.8),
                borderColor: options.borderColor || { r: 0.1, g: 0.1, b: 0.1 },
                fillColor: options.color || null
            });
        }

        drawPolygon(options = {}) {
            if (!options.points || options.points.length < 3) return;
            this.polygons.push({
                points: options.points,
                fillColor: options.color || null,
                borderColor: options.borderColor || null,
                borderWidth: Number(options.borderWidth || 0.8)
            });
        }

        getSize() {
            return { width: 595.32, height: 841.92 };
        }
    }

    class NativePDFDocument {
        constructor(rawBuffer) {
            const src = rawBuffer instanceof Uint8Array ? rawBuffer : new Uint8Array(rawBuffer);
            this.rawBytes = new Uint8Array(src.length);
            this.rawBytes.set(src);
            this.pdfText = bytesToLatin1(this.rawBytes);
            this.pages = [];
            this.pagesRootObjId = 2;
            this._discoverPages();
        }

        static async load(rawBuffer) {
            return new NativePDFDocument(rawBuffer);
        }

        static async create() {
            const minimalShell =
                "%PDF-1.7\n" +
                "1 0 obj\n<< /Type /Catalog /Pages 2 0 R >>\nendobj\n" +
                "2 0 obj\n<< /Type /Pages /Count 0 /Kids [ ] >>\nendobj\n" +
                "trailer\n<< /Root 1 0 R >>\n%%EOF\n";
            const doc = new NativePDFDocument(latin1ToBytes(minimalShell));
            doc.pages = [];
            doc.pagesRootObjId = 2;
            return doc;
        }

        _discoverPages() {
            const pagesRootMatch = this.pdfText.match(/(\d+)\s+0\s+obj\s*<<[\s\S]*?\/Type\s*\/Pages\b[\s\S]*?\/Kids\s*\[\s*([^\]]+)\][\s\S]*?endobj/);
            const pageObjIds = [];

            if (pagesRootMatch) {
                this.pagesRootObjId = parseInt(pagesRootMatch[1], 10);
                const refs = pagesRootMatch[2].match(/(\d+)\s+0\s+R/g) || [];
                refs.forEach(r => pageObjIds.push(parseInt(r, 10)));
            } else {
                const pageRegex = /(\d+)\s+0\s+obj\s*<<([\s\S]*?)>>\s*endobj/g;
                let m;
                while ((m = pageRegex.exec(this.pdfText)) !== null) {
                    if (/\/Type\s*\/Page\b/.test(m[2])) {
                        pageObjIds.push(parseInt(m[1], 10));
                    }
                }
            }

            if (pageObjIds.length === 0) {
                [1, 2, 3].forEach((id, idx) => this.pages.push(new NativePageProxy(idx, id, false)));
            } else {
                pageObjIds.forEach((objId, idx) => {
                    this.pages.push(new NativePageProxy(idx, objId, false));
                });
            }
        }

        getPages() {
            return this.pages;
        }

        addPage() {
            const newPage = new NativePageProxy(this.pages.length, null, true);
            this.pages.push(newPage);
            return newPage;
        }

        async embedFont(fontName) {
            return { name: fontName || "Helvetica" };
        }

        _buildPageStreamPayload(page, isExistingPage) {
            const cmds = isExistingPage ? ["Q", "q"] : ["q"];

            // 1. Draw Polygons (Logos / Badges)
            if (page.polygons && page.polygons.length > 0) {
                for (const poly of page.polygons) {
                    const pts = poly.points;
                    let pCmd = "q ";
                    if (poly.fillColor) {
                        const fc = poly.fillColor;
                        pCmd += `${fc.r.toFixed(3)} ${fc.g.toFixed(3)} ${fc.b.toFixed(3)} rg `;
                    }
                    if (poly.borderColor) {
                        const bc = poly.borderColor;
                        pCmd += `${poly.borderWidth.toFixed(2)} w ${bc.r.toFixed(3)} ${bc.g.toFixed(3)} ${bc.b.toFixed(3)} RG `;
                    }
                    pCmd += `${pts[0].x.toFixed(2)} ${pts[0].y.toFixed(2)} m `;
                    for (let i = 1; i < pts.length; i++) {
                        pCmd += `${pts[i].x.toFixed(2)} ${pts[i].y.toFixed(2)} l `;
                    }
                    pCmd += "h ";
                    pCmd += (poly.fillColor && poly.borderColor) ? "B" : (poly.fillColor ? "f" : "S");
                    pCmd += " Q";
                    cmds.push(pCmd);
                }
            }

            // 2. Draw Rectangles (Tables / Boxes)
            if (page.rects && page.rects.length > 0) {
                for (const r of page.rects) {
                    let rCmd = "q ";
                    if (r.fillColor) {
                        const fc = r.fillColor;
                        rCmd += `${fc.r.toFixed(3)} ${fc.g.toFixed(3)} ${fc.b.toFixed(3)} rg `;
                    }
                    if (r.borderColor && r.borderWidth > 0) {
                        const bc = r.borderColor;
                        rCmd += `${r.borderWidth.toFixed(2)} w ${bc.r.toFixed(3)} ${bc.g.toFixed(3)} ${bc.b.toFixed(3)} RG `;
                    }
                    const op = (r.fillColor && r.borderColor && r.borderWidth > 0) ? "B" : (r.fillColor ? "f" : "S");
                    rCmd += `${r.x.toFixed(2)} ${r.y.toFixed(2)} ${r.width.toFixed(2)} ${r.height.toFixed(2)} re ${op} Q`;
                    cmds.push(rCmd);
                }
            }

            // 3. Draw Lines
            if (page.lines && page.lines.length > 0) {
                for (const ln of page.lines) {
                    const c = ln.color || { r: 0.2, g: 0.2, b: 0.2 };
                    cmds.push(
                        `q ${ln.thickness.toFixed(2)} w ${c.r.toFixed(3)} ${c.g.toFixed(3)} ${c.b.toFixed(3)} RG ${ln.x1.toFixed(2)} ${ln.y1.toFixed(2)} m ${ln.x2.toFixed(2)} ${ln.y2.toFixed(2)} l S Q`
                    );
                }
            }

            // 4. Draw Text & Tick Marks
            for (const op of page.operations) {
                const c = op.color || { r: 0.05, g: 0.12, b: 0.28 };
                const xNum = Number(op.x || 0);
                const yNum = Number(op.y || 0);
                const szNum = Number(op.size || 8.5);

                if (op.text === "✓" || op.text === "✔") {
                    const x1 = (xNum + 0.5).toFixed(2);
                    const y1 = (yNum + szNum * 0.35).toFixed(2);
                    const x2 = (xNum + szNum * 0.35).toFixed(2);
                    const y2 = (yNum + 0.5).toFixed(2);
                    const x3 = (xNum + szNum * 0.90).toFixed(2);
                    const y3 = (yNum + szNum * 0.85).toFixed(2);
                    cmds.push(
                        `q 1.6 w 1 J 1 j ${c.r.toFixed(3)} ${c.g.toFixed(3)} ${c.b.toFixed(3)} RG ${x1} ${y1} m ${x2} ${y2} l ${x3} ${y3} l S Q`
                    );
                } else {
                    const escaped = escapePdfLiteralString(op.text);
                    const fontKey = op.bold ? "/F_WCRE" : "/F_REG";
                    const x = xNum.toFixed(2);
                    const y = yNum.toFixed(2);
                    const sz = szNum.toFixed(2);
                    cmds.push(
                        `BT ${fontKey} ${sz} Tf ${c.r.toFixed(3)} ${c.g.toFixed(3)} ${c.b.toFixed(3)} rg 1 0 0 1 ${x} ${y} Tm (${escaped}) Tj ET`
                    );
                }
            }

            cmds.push("Q");
            return cmds.join("\n") + "\n";
        }

        async save() {
            let maxObjId = 0;
            const objScan = /(\d+)\s+0\s+obj\b/g;
            let m;
            while ((m = objScan.exec(this.pdfText)) !== null) {
                const id = parseInt(m[1], 10);
                if (id > maxObjId) maxObjId = id;
            }

            const prevXrefMatch = this.pdfText.match(/startxref\s+(\d+)\s+%%EOF\s*$/);
            const rootMatch = this.pdfText.match(/\/Root\s+(\d+\s+0\s+R)/);
            const infoMatch = this.pdfText.match(/\/Info\s+(\d+\s+0\s+R)/);

            let nextId = maxObjId + 1;
            const boldFontObjId = nextId++;
            const regFontObjId = nextId++;
            const qPushObjId = nextId++;

            const appendedObjects = [];

            appendedObjects.push({
                id: boldFontObjId,
                body: `${boldFontObjId} 0 obj\n<<\n/Type /Font\n/Subtype /Type1\n/BaseFont /Helvetica-Bold\n/Encoding /WinAnsiEncoding\n>>\nendobj\n`
            });
            appendedObjects.push({
                id: regFontObjId,
                body: `${regFontObjId} 0 obj\n<<\n/Type /Font\n/Subtype /Type1\n/BaseFont /Helvetica\n/Encoding /WinAnsiEncoding\n>>\nendobj\n`
            });

            const qStreamContent = "q\n";
            appendedObjects.push({
                id: qPushObjId,
                body: `${qPushObjId} 0 obj\n<<\n/Length ${qStreamContent.length}\n>>\nstream\n${qStreamContent}endstream\nendobj\n`
            });

            const finalPageKidsRefs = [];

            for (const page of this.pages) {
                if (!page.isNewPage) {
                    finalPageKidsRefs.push(`${page.pageObjId} 0 R`);
                    if (!page.operations.length && !page.lines.length && !page.rects.length) continue;

                    const streamPayload = this._buildPageStreamPayload(page, true);
                    const textStreamObjId = nextId++;
                    appendedObjects.push({
                        id: textStreamObjId,
                        body: `${textStreamObjId} 0 obj\n<<\n/Length ${streamPayload.length}\n>>\nstream\n${streamPayload}endstream\nendobj\n`
                    });

                    const pageRegex = new RegExp(`(?:^|\\r?\\n)${page.pageObjId}\\s+0\\s+obj\\s*<<([\\s\\S]*?)>>\\s*endobj`);
                    const pageMatch = this.pdfText.match(pageRegex);
                    if (pageMatch) {
                        let pageDict = pageMatch[1];

                        if (/\/Contents\s*\[([^\]]*)\]/.test(pageDict)) {
                            pageDict = pageDict.replace(/\/Contents\s*\[([^\]]*)\]/, (full, inner) => {
                                return `/Contents [ ${qPushObjId} 0 R ${inner.trim()} ${textStreamObjId} 0 R ]`;
                            });
                        } else if (/\/Contents\s+(\d+\s+0\s+R)/.test(pageDict)) {
                            pageDict = pageDict.replace(/\/Contents\s+(\d+\s+0\s+R)/, (full, singleRef) => {
                                return `/Contents [ ${qPushObjId} 0 R ${singleRef} ${textStreamObjId} 0 R ]`;
                            });
                        }

                        const resRefMatch = pageDict.match(/\/Resources\s+(\d+)\s+0\s+R/);
                        if (resRefMatch) {
                            const resObjId = parseInt(resRefMatch[1], 10);
                            const resRegex = new RegExp(`(?:^|\\r?\\n)${resObjId}\\s+0\\s+obj\\s*<<([\\s\\S]*?)>>\\s*endobj`);
                            const resMatch = this.pdfText.match(resRegex);
                            if (resMatch) {
                                let resDict = resMatch[1];
                                if (/\/Font\s*<</.test(resDict)) {
                                    resDict = resDict.replace(/\/Font\s*<</, `/Font << /F_WCRE ${boldFontObjId} 0 R /F_REG ${regFontObjId} 0 R `);
                                } else {
                                    resDict = `\n/Font << /F_WCRE ${boldFontObjId} 0 R /F_REG ${regFontObjId} 0 R >>` + resDict;
                                }
                                appendedObjects.push({
                                    id: resObjId,
                                    body: `${resObjId} 0 obj\n<<${resDict}>>\nendobj\n`
                                });
                            }
                        } else {
                            pageDict += `\n/Resources << /Font << /F_WCRE ${boldFontObjId} 0 R /F_REG ${regFontObjId} 0 R >> >>\n`;
                        }

                        appendedObjects.push({
                            id: page.pageObjId,
                            body: `${page.pageObjId} 0 obj\n<<${pageDict}>>\nendobj\n`
                        });
                    }
                } else {
                    const newPageStreamObjId = nextId++;
                    const newPageObjId = nextId++;
                    page.pageObjId = newPageObjId;
                    finalPageKidsRefs.push(`${newPageObjId} 0 R`);

                    const streamPayload = this._buildPageStreamPayload(page, false);
                    appendedObjects.push({
                        id: newPageStreamObjId,
                        body: `${newPageStreamObjId} 0 obj\n<<\n/Length ${streamPayload.length}\n>>\nstream\n${streamPayload}endstream\nendobj\n`
                    });

                    appendedObjects.push({
                        id: newPageObjId,
                        body: `${newPageObjId} 0 obj\n<<\n/Type /Page\n/Parent ${this.pagesRootObjId} 0 R\n/MediaBox [ 0.0 0.0 595.32 841.92 ]\n/CropBox [ 0.0 0.0 595.32 841.92 ]\n/Resources << /Font << /F_WCRE ${boldFontObjId} 0 R /F_REG ${regFontObjId} 0 R >> >>\n/Contents ${newPageStreamObjId} 0 R\n/Rotate 0\n>>\nendobj\n`
                    });
                }
            }

            if (this.pages.some(p => p.isNewPage)) {
                appendedObjects.push({
                    id: this.pagesRootObjId,
                    body: `${this.pagesRootObjId} 0 obj\n<<\n/Type /Pages\n/Count ${finalPageKidsRefs.length}\n/Kids [ ${finalPageKidsRefs.join(" ")} ]\n>>\nendobj\n`
                });
            }

            let baseLength = this.rawBytes.length;
            let appendChunk = "\n";
            const newOffsets = {};

            for (const obj of appendedObjects) {
                newOffsets[obj.id] = baseLength + appendChunk.length;
                appendChunk += obj.body;
            }

            const allOffsets = { 0: 0 };
            const fullObjRegex = /(?:^|\r?\n)(\d+)\s+0\s+obj\b/g;
            let om;
            while ((om = fullObjRegex.exec(this.pdfText)) !== null) {
                const id = parseInt(om[1], 10);
                const offset = om.index + (om[0].startsWith("\r\n") ? 2 : (om[0].startsWith("\n") || om[0].startsWith("\r") ? 1 : 0));
                allOffsets[id] = offset;
            }
            for (const idStr in newOffsets) {
                allOffsets[parseInt(idStr, 10)] = newOffsets[idStr];
            }

            const totalSize = nextId;
            const xrefOffset = baseLength + appendChunk.length;
            let xrefSection = `xref\n0 ${totalSize}\n0000000000 65535 f \n`;
            for (let i = 1; i < totalSize; i++) {
                const off = allOffsets[i] || 0;
                const padded = String(off).padStart(10, "0");
                xrefSection += `${padded} 00000 n \n`;
            }

            const rootEntry = rootMatch ? `/Root ${rootMatch[1]}\n` : "/Root 1 0 R\n";
            const infoEntry = infoMatch ? `/Info ${infoMatch[1]}\n` : "";
            const prevEntry = prevXrefMatch ? `/Prev ${prevXrefMatch[1]}\n` : "";

            const trailerSection = `trailer\n<<\n/Size ${totalSize}\n${rootEntry}${infoEntry}${prevEntry}>>\nstartxref\n${xrefOffset}\n%%EOF\n`;

            const finalAppendBytes = latin1ToBytes(appendChunk + xrefSection + trailerSection);
            const combined = new Uint8Array(this.rawBytes.length + finalAppendBytes.length);
            combined.set(this.rawBytes, 0);
            combined.set(finalAppendBytes, this.rawBytes.length);
            return combined;
        }
    }

    const LocalPdfLib = {
        PDFDocument: NativePDFDocument,
        StandardFonts: {
            Helvetica: "Helvetica",
            HelveticaBold: "Helvetica-Bold"
        },
        rgb: function (r, g, b) {
            return { r, g, b };
        },
        isNativeLocalEngine: true
    };

    globalScope.LocalPdfLib = LocalPdfLib;
    globalScope.PDFLib = LocalPdfLib;
    console.log("[PDFLib Engine] Native PDF-1.7 Stamping, Addendum & Receipt Compiler initialized.");
})(typeof window !== "undefined" ? window : globalThis);
